package com.lexorion.payroll.repository;
import com.lexorion.payroll.domain.CompensationProfile;import java.time.LocalDate;import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;
public interface CompensationProfileRepository extends JpaRepository<CompensationProfile,UUID>{List<CompensationProfile>findByPayrollEmployeeWorkspaceIdAndPayrollEmployeeEmployeeCodeOrderByEffectiveFromAsc(UUID workspaceId,String employeeCode);Optional<CompensationProfile>findByPayrollEmployeeWorkspaceIdAndPayrollEmployeeEmployeeCodeAndProfileKey(UUID workspaceId,String employeeCode,String profileKey);@Query("select distinct p from CompensationProfile p left join fetch p.assignments a left join fetch a.definition where p.payrollEmployee.workspace.id=:workspaceId and p.payrollEmployee.employeeCode=:employeeCode and p.status=com.lexorion.payroll.domain.CompensationProfileStatus.ACTIVE and p.effectiveFrom<=:date and (p.effectiveTo is null or p.effectiveTo>=:date)")List<CompensationProfile>findEffective(@Param("workspaceId")UUID workspaceId,@Param("employeeCode")String employeeCode,@Param("date")LocalDate date);@Query("select count(p) from CompensationProfile p where p.payrollEmployee.id=:employeeId and (:end is null or p.effectiveFrom<=:end) and (p.effectiveTo is null or p.effectiveTo>=:start)")long countOverlaps(@Param("employeeId")UUID employeeId,@Param("start")LocalDate start,@Param("end")LocalDate end);}
